    public static JsonObject Schema(string name) => Schemas[name]?.DeepClone().AsObject() ?? throw new ArgumentException("Unknown U1 schema.", nameof(name));

    public static void Validate(JsonObject schema, JsonObject body)
    {
        var properties = schema["properties"]!.AsObject();
        foreach (var required in schema["required"]?.AsArray() ?? [])
            if (!body.ContainsKey(required!.GetValue<string>())) throw new ArgumentException($"{required}: required.");
        foreach (var pair in body)
        {
            if (properties[pair.Key] is not JsonObject definition) throw new ArgumentException($"{pair.Key}: unsupported field.");
            ValidateValue(pair.Key, definition, pair.Value);
        }
    }

    public static void ValidateValue(string key, JsonObject definition, JsonNode? value)
    {
        var type = definition["type"];
        var types = type is JsonArray array ? array.Select(node => node!.GetValue<string>()).ToArray() : [type?.GetValue<string>() ?? "json"];
        if (value == null)
        {
            if (!types.Contains("null")) throw new ArgumentException($"{key}: null is not permitted.");
            return;
        }
        if (definition["enum"] is JsonArray options && !options.Any(option => JsonNode.DeepEquals(option, value)))
            throw new ArgumentException($"{key}: choose a supported value.");
        var valid = types.Any(kind => kind switch
        {
            "string" => value is JsonValue scalar && scalar.TryGetValue<string>(out _),
            "boolean" => value is JsonValue scalar && scalar.TryGetValue<bool>(out _),
            "integer" => UserJson.TryInteger(value, out _),
            "number" => UserJson.TryNumber(value, out _),
            "array" => value is JsonArray,
            "object" => value is JsonObject,
            "json" => true,
            _ => false
        });
        if (!valid) throw new ArgumentException($"{key}: invalid value type.");
        if (value is JsonValue text && text.TryGetValue<string>(out var content))
        {
            var length = content.EnumerateRunes().Count();
            if (definition["minLength"] is JsonValue min && length < min.GetValue<int>() ||
                definition["maxLength"] is JsonValue max && length > max.GetValue<int>()) throw new ArgumentException($"{key}: invalid length.");
            if ((key == "password" || key == "pin") && Encoding.UTF8.GetByteCount(content) > 72) throw new ArgumentException($"{key}: maximum 72 UTF-8 bytes.");
        }
        if (UserJson.TryNumber(value, out var numeric))
        {
            if (definition["minimum"] is JsonValue min && numeric < min.GetValue<double>() ||
                definition["maximum"] is JsonValue max && numeric > max.GetValue<double>()) throw new ArgumentException($"{key}: outside the supported range.");
        }
        if (value is JsonArray entries && definition["items"] is JsonObject item)
            foreach (var entry in entries) ValidateValue(key, item, entry);
    }
